    [8]*11,
    [8]*11,
    [8,1,8,8,8,8,8,8,8,8,8],  # (6,1) = 1
    [8]*11
]

d2_out = [
    [8,6,8,8,8,8,8,8,8,8,8],  # (0,1)=6
    [8,8,6,8,8,8,1,8,8,8,8],  # (1,2)=6, (1,6)=1
    [8,8,8,6,8,1,8,8,8,8,8],  # (2,3)=6, (2,5)=1
    [8,8,8,8,6,8,8,8,8,8,8],  # (3,4)=6
    [8,8,8,1,8,6,8,8,8,8,8],  # (4,3)=1, (4,5)=6
    [8,8,1,8,8,8,6,8,8,8,8],  # (5,2)=1, (5,6)=6
    [8,1,8,8,8,8,8,6,8,8,8],  # (6,1)=1, (6,7)=6
    [8,8,8,8,8,8,8,8,6,8,8],  # (7,8)=6
]

# Find all non-background points
def get_points(grid):
    points = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 8:
                color = grid[r][c]
                if color not in points:
                    points[color] = []
                points[color].append((r, c))
    return points

print("Input points:")
print("  Blue (1):", get_points(d2_in)[1])
print("  Magenta (6):", get_points(d2_in)[6])

print("\nOutput points (non-8):")
points_8 = []
for r in range(len(d2_out)):
    for c in range(len(d2_out[0])):
        if d2_out[r][c] != 8:
            points_8.append((r, c, d2_out[r][c]))
for p in points_8:
    print(f"  {p[0]},{p[1]} = {p[2]}")

