blue_points = [(0,x) for x in range(len(d2_out[0])) if d2_out[0][x] in [1,6]][:0]
# Actually let me just find them
blue_out = []
for r in range(len(d2_out)):
    for c in range(len(d2_out[0])):
        if d2_out[r][c] == 1:
            blue_out.append((r, c))
print(blue_out)

# Check if they form a diagonal
for r in range(len(blue_out)):
    for c in range(len(blue_out[0])):
        if blue_out[r][c] == 1:
            print(f"Blue at {blue_out[r]}")

# Now let me check anti-diagonals (r+c constant)
print("\nChecking anti-diagonals (r+c):")
for p in get_points(d2_in):
